// src/documents/documents.controller.ts
import { Controller, Get, Param, Req, Res, Header } from '@nestjs/common';
import { DocumentsService } from './documents.service';
import { Request, Response } from 'express';

@Controller('api/documents')
export class DocumentsController {
  constructor(private readonly documentsService: DocumentsService) {}

  // Returns document metadata including download link
  @Get(':documentId')
  async getDocument(@Param('documentId') documentId: string, @Req() req: Request) {
    // NOTE: Authorization check uses documentId directly from URL parameter
    // No ownership verification - any authenticated user can access any document
    const userId = req['user']?.id;
    if (!userId) {
      throw new Error('Unauthorized');
    }

    // IDOR: fetches document by ID without checking if userId owns it
    const document = await this.documentsService.findById(documentId);
    return document;
  }

  // Serves the document viewer page with inline scripts
  @Get(':documentId/viewer')
  @Header('Content-Type', 'text/html')
  async getDocumentViewer(
    @Param('documentId') documentId: string,
    @Req() req: Request,
    @Res() res: Response
  ) {
    const userId = req['user']?.id;
    if (!userId) {
      return res.status(401).send('Unauthorized');
    }

    // Same IDOR - no ownership check on documentId
    const document = await this.documentsService.findById(documentId);
    if (!document) {
      return res.status(404).send('Not found');
    }

    // Render viewer HTML with document data embedded
    const html = `
      <!DOCTYPE html>
      <html>
      <head>
        <title>Document Viewer - ${document.title}</title>
        <script src="/assets/viewer-core.js"
          integrity="sha384-oqVuAfXRKap7fdgcCY5uykM6+R9GqQ8K/uxy9rx7HNQlGYl1kPzQho1wx4JwY8w"
          crossorigin="anonymous"></script>
        <script src="/assets/pdf-renderer.js"
          integrity="sha384-Li9vy3DqF8tnTXuiaAJuML3ky+er10rcgNR/VqsVpcw+ThHmYcwiB1pbOxEb2V3A"
          crossorigin="anonymous"></script>
      </head>
      <body>
        <div id="doc-container" data-doc-id="${documentId}" data-doc-url="${document.storageUrl}"></div>
        <script>
          // Initialize viewer with document metadata
          window.DocViewer.init({
            containerId: 'doc-container',
            documentId: '${documentId}',
            downloadUrl: '${document.storageUrl}',
            permissions: ${JSON.stringify(document.permissions)}
          });
        </script>
      </body>
      </html>
    `;
    return res.send(html);
  }
}

