import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

@Entity()
export class Document {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  title: string;

  @Column()
  ownerId: string;

  @Column()
  storageUrl: string;

  @Column('json')
  permissions: Record<string, any>;

  @Column({ default: false })
  isPublic: boolean;
}
